import json
import base64
import hashlib
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad

# Lambda handler for Step Functions "DecryptPayload" state
# Processes encrypted session tokens from partner integrations

SECRET_KEY = None  # Injected via environment variable at runtime

def get_key():
    import os
    global SECRET_KEY
    if SECRET_KEY is None:
        raw = os.environ.get('ENCRYPTION_KEY', 'default-dev-key-0000')
        SECRET_KEY = hashlib.sha256(raw.encode()).digest()
    return SECRET_KEY

def decrypt_token(ciphertext_b64):
    """Decrypt AES-CBC token with PKCS7 padding.
    Returns plaintext or raises specific error on padding failure."""
    raw = base64.b64decode(ciphertext_b64)
    if len(raw) < 32:
        raise ValueError("Ciphertext too short")

    iv = raw[:16]
    ciphertext = raw[16:]

    cipher = AES.new(get_key(), AES.MODE_CBC, iv)
    plaintext_padded = cipher.decrypt(ciphertext)

    # Validate PKCS7 padding
    try:
        plaintext = unpad(plaintext_padded, AES.block_size)
    except ValueError as e:
        # Padding validation failed - return specific error
        raise PaddingError("Invalid token structure")

    return plaintext

class PaddingError(Exception):
    pass

class TokenExpiredError(Exception):
    pass

def validate_token_contents(plaintext):
    """Parse decrypted token and validate expiry."""
    import time
    try:
        data = json.loads(plaintext.decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError):
        raise ValueError("Malformed token payload")

    if 'exp' in data and data['exp'] < time.time():
        raise TokenExpiredError("Token expired")

    return data

def lambda_handler(event, context):
    """Step Functions state: DecryptAndValidatePartnerToken

    Input: {"encrypted_token": "<base64>", "partner_id": "..."}
    Output: {"status": "...", "data": {...}} or error details
    """
    encrypted_token = event.get('encrypted_token')
    partner_id = event.get('partner_id', 'unknown')

    if not encrypted_token:
        return {
            'status': 'error',
            'error_type': 'missing_input',
            'message': 'No encrypted_token provided'
        }

    try:
        plaintext = decrypt_token(encrypted_token)
        token_data = validate_token_contents(plaintext)
        return {
            'status': 'success',
            'partner_id': partner_id,
            'data': token_data
        }
    except PaddingError:
        # Distinguishable error for padding failures
        return {
            'status': 'error',
            'error_type': 'padding_error',
            'message': 'Token decryption failed - invalid structure'
        }
    except TokenExpiredError:
        return {
            'status': 'error', 
            'error_type': 'token_expired',
            'message': 'Token has expired'
        }
    except ValueError as e:
        return {
            'status': 'error',
            'error_type': 'invalid_token',
            'message': str(e)
        }
    except Exception as e:
        return {
            'status': 'error',
            'error_type': 'internal_error',
            'message': 'Processing failed'
        }
